import{_ as e,o as l,c as i,a6 as r}from"./chunks/framework.COmIsZrZ.js";const c=JSON.parse('{"title":"图鉴与百科系统","description":"","frontmatter":{"readingTime":"2 min read"},"headers":[],"relativePath":"项目实践/JRPG/G_UI与交互/图鉴与百科.md","filePath":"项目实践/JRPG/G_UI与交互/图鉴与百科.md"}'),t={name:"项目实践/JRPG/G_UI与交互/图鉴与百科.md"};function o(_,a,h,n,d,s){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="图鉴与百科系统" tabindex="-1">图鉴与百科系统 <a class="header-anchor" href="#图鉴与百科系统" aria-label="Permalink to &quot;图鉴与百科系统&quot;">​</a></h1><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>用于记录游戏中的世界观背景、敌人信息、收集品以及剧情碎片，增强玩家的沉浸感和收集动力。</p><h2 id="_2-模块细分" tabindex="-1">2. 模块细分 <a class="header-anchor" href="#_2-模块细分" aria-label="Permalink to &quot;2. 模块细分&quot;">​</a></h2><h3 id="_2-1-上海纪闻-报纸系统" tabindex="-1">2.1 上海纪闻 (报纸系统) <a class="header-anchor" href="#_2-1-上海纪闻-报纸系统" aria-label="Permalink to &quot;2.1 上海纪闻 (报纸系统)&quot;">​</a></h3><ul><li>收集散落在地图各处的报纸碎片。</li><li>内容：记录历史事件、社会动态、血案传闻。</li><li>奖励：收集进度可解锁世界观背景条目。</li></ul><h3 id="_2-2-娲术残篇-知识库" tabindex="-1">2.2 娲术残篇 (知识库) <a class="header-anchor" href="#_2-2-娲术残篇-知识库" aria-label="Permalink to &quot;2.2 娲术残篇 (知识库)&quot;">​</a></h3><ul><li>来源：古籍、卷轴、羊皮纸。</li><li>内容：解释娲术原理、血族起源、妖兽弱点。</li><li>作用：提供战斗增益（如了解弱点后增加伤害）。</li></ul><h3 id="_2-3-怪物图鉴" tabindex="-1">2.3 怪物图鉴 <a class="header-anchor" href="#_2-3-怪物图鉴" aria-label="Permalink to &quot;2.3 怪物图鉴&quot;">​</a></h3><ul><li>记录遭遇过的敌人信息（属性、掉落、弱点）。</li><li>随着战斗次数增加，信息越详细。</li></ul><h3 id="_2-4-角色手记" tabindex="-1">2.4 角色手记 <a class="header-anchor" href="#_2-4-角色手记" aria-label="Permalink to &quot;2.4 角色手记&quot;">​</a></h3><ul><li>林晚晴的医案</li><li>朱利安的草图笔记</li><li>陈少秋的调查报告</li></ul><h2 id="_3-ui表现" tabindex="-1">3. UI表现 <a class="header-anchor" href="#_3-ui表现" aria-label="Permalink to &quot;3. UI表现&quot;">​</a></h2><p>（待补充）</p>',14)])])}const m=e(t,[["render",o]]);export{c as __pageData,m as default};
